local function materiau(nom: string): Enum.Material
	local ok, m = pcall(function()
		return (Enum.Material :: any)[nom]
	end)
	return if ok and typeof(m) == "EnumItem" then m else Enum.Material.SmoothPlastic
end

local function particules(parent: BasePart)
	local e = Instance.new("ParticleEmitter")
	e.Name = "Scintillement"
	e.Texture = "rbxasset://textures/particles/sparkles_main.dds"
	e.Color = ColorSequence.new(Color3.fromRGB(255, 255, 255), Color3.fromRGB(170, 210, 255))
	e.LightEmission = 1
	e.LightInfluence = 0
	e.Rate = 3
	e.Lifetime = NumberRange.new(0.6, 1.2)
	e.Speed = NumberRange.new(0.05, 0.2)
	e.SpreadAngle = Vector2.new(180, 180)
	e.Acceleration = Vector3.new(0, 0, 0)
	e.Drag = 0.6
	e.RotSpeed = NumberRange.new(-120, 120)
	e.Size = NumberSequence.new({
		NumberSequenceKeypoint.new(0, 0),
		NumberSequenceKeypoint.new(0.4, 0.12),
		NumberSequenceKeypoint.new(1, 0),
	})
	e.Transparency = NumberSequence.new(0.1, 1)
	e.Parent = parent
end

local function construire(): Model
	local modele = Instance.new("Model")
	modele.Name = "CasqueDiamant"
	modele:SetAttribute("NomAffiche", "Casque de Diamant")

	local racine = Instance.new("Part")
	racine.Name = "Racine"
	racine.Size = Vector3.new(0.2, 0.2, 0.2)
	racine.CFrame = CFrame.identity
	racine.Transparency = 1
	racine.CastShadow = false
	racine.Anchored = false
	racine.CanCollide, racine.CanQuery, racine.CanTouch = false, false, false
	racine.Massless = true
	racine.Parent = modele
	modele.PrimaryPart = racine

	local lumiereFaite = false
	for _, pc in PIECES do
		local nom, cle, forme, taille, cf, marque = pc[1], pc[2], pc[3], pc[4], pc[5], pc[6]
		local c = COULEURS[cle]
		local p: BasePart = if forme == "Coin" then Instance.new("WedgePart") else Instance.new("Part")
		p.Name = nom
		p.Size = taille
		p.CFrame = cf
		p.Anchored = false
		p.CanCollide, p.CanQuery, p.CanTouch = false, false, false
		p.Massless = true
		p.TopSurface, p.BottomSurface = Enum.SurfaceType.Smooth, Enum.SurfaceType.Smooth
		p.Material = materiau(c[1])
		p.Color = Color3.fromRGB(c[2], c[3], c[4])
		p.Reflectance = c[5]
		p.CastShadow = c[1] ~= "Neon"
		if marque == "lumiere" and not lumiereFaite then
			lumiereFaite = true
			local l = Instance.new("PointLight")
			l.Color = Color3.fromRGB(200, 230, 255)
			l.Range = 7
			l.Brightness = 1
			l.Shadows = false
			l.Parent = p
			particules(p)
		end
		p.Parent = modele
		local w = Instance.new("WeldConstraint")
		w.Part0 = racine
		w.Part1 = p
		w.Parent = p
	end
	return modele
end

return {
	Nom = "Casque de Diamant",
	Format = "Code",
	Taille = Vector3.new(1.9526, 2.4161, 2.0531),
	Centre = Vector3.new(0, 0.3218, -0.0064), -- centre de la boîte englobante dans le repère de la tête
	construire = construire,
}
